const express = require('express');
const crypto = require('crypto');
const app = express();

// In-memory store
const users = new Map();
const sessions = new Map();

// Role hierarchy: admin > manager > user
const ROLE_HIERARCHY = { admin: 3, manager: 2, user: 1 };

// Middleware to parse JSON
app.use(express.json());

// Session middleware
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || !sessions.has(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.session = sessions.get(token);
  req.user = users.get(req.session.userId);
  if (!req.user) {
    return res.status(401).json({ error: 'User not found' });
  }
  next();
}

// Authorization middleware factory
function requireRole(minimumRole) {
  return function(req, res, next) {
    const userRole = req.user.role;
    const userLevel = ROLE_HIERARCHY[userRole] || 0;
    const requiredLevel = ROLE_HIERARCHY[minimumRole] || 0;
    if (userLevel >= requiredLevel) {
      return next();
    }
    return res.status(403).json({ error: 'Insufficient permissions' });
  };
}

// Role transition validator - checks if a role change is permitted
function validateRoleTransition(currentRole, targetRole, actorRole) {
  const actorLevel = ROLE_HIERARCHY[actorRole] || 0;
  const targetLevel = ROLE_HIERARCHY[targetRole] || 0;
  const currentLevel = ROLE_HIERARCHY[currentRole] || 0;

  // Actor must have higher privilege than both current and target roles
  // This prevents privilege escalation
  if (actorLevel > currentLevel && actorLevel > targetLevel) {
    return { valid: true };
  }
  return { valid: false, reason: 'Cannot modify roles at or above your level' };
}

// Compute effective permissions based on role and any delegated permissions
function computeEffectivePermissions(user) {
  const basePermissions = {
    admin: ['read', 'write', 'delete', 'manage_users', 'manage_roles', 'view_audit'],
    manager: ['read', 'write', 'delete', 'manage_users'],
    user: ['read', 'write']
  };

  const permissions = new Set(basePermissions[user.role] || []);

  // Add delegated permissions from user's delegation chain
  if (user.delegatedPermissions) {
    for (const perm of user.delegatedPermissions) {
      permissions.add(perm);
    }
  }

  return Array.from(permissions);
}

// Registration endpoint
app.post('/api/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  const userId = crypto.randomUUID();
  const passwordHash = crypto.createHash('sha256').update(password + userId).digest('hex');

  users.set(userId, {
    id: userId,
    username,
    passwordHash,
    role: 'user',
    delegatedPermissions: [],
    createdAt: Date.now()
  });

  return res.status(201).json({ userId, username, role: 'user' });
});

// Login endpoint
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  let foundUser = null;

  for (const [id, user] of users) {
    if (user.username === username) {
      foundUser = user;
      break;
    }
  }

  if (!foundUser) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const hash = crypto.createHash('sha256').update(password + foundUser.id).digest('hex');
  if (hash !== foundUser.passwordHash) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId: foundUser.id, createdAt: Date.now() });

  return res.json({ token, role: foundUser.role });
});

// Get user profile
app.get('/api/users/:userId', authenticate, (req, res) => {
  const targetUser = users.get(req.params.userId);
  if (!targetUser) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Users can view their own profile, managers+ can view any
  if (req.user.id !== targetUser.id) {
    const userLevel = ROLE_HIERARCHY[req.user.role] || 0;
    if (userLevel < ROLE_HIERARCHY['manager']) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
  }

  return res.json({
    id: targetUser.id,
    username: targetUser.username,
    role: targetUser.role,
    permissions: computeEffectivePermissions(targetUser)
  });
});

// Admin endpoint: Update user role
app.put('/api/users/:userId/role', authenticate, requireRole('admin'), (req, res) => {
  const { role } = req.body;
  const targetUser = users.get(req.params.userId);

  if (!targetUser) {
    return res.status(404).json({ error: 'User not found' });
  }

  if (!ROLE_HIERARCHY[role]) {
    return res.status(400).json({ error: 'Invalid role' });
  }

  const transition = validateRoleTransition(targetUser.role, role, req.user.role);
  if (!transition.valid) {
    return res.status(403).json({ error: transition.reason });
  }

  targetUser.role = role;
  return res.json({ success: true, userId: targetUser.id, newRole: role });
});

// Delegate permissions to another user
app.post('/api/users/:userId/delegate', authenticate, requireRole('manager'), (req, res) => {
  const { permissions } = req.body;
  const targetUser = users.get(req.params.userId);

  if (!targetUser) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Validate that actor has the permissions they're trying to delegate
  const actorPermissions = computeEffectivePermissions(req.user);
  const invalidPerms = permissions.filter(p => !actorPermissions.includes(p));

  if (invalidPerms.length > 0) {
    return res.status(403).json({ error: `Cannot delegate permissions you don't have: ${invalidPerms.join(', ')}` });
  }

  // Apply delegated permissions
  targetUser.delegatedPermissions = [
    ...new Set([...targetUser.delegatedPermissions, ...permissions])
  ];

  return res.json({
    success: true,
    userId: targetUser.id,
    effectivePermissions: computeEffectivePermissions(targetUser)
  });
});

// Admin panel - list all users
app.get('/api/admin/users', authenticate, requireRole('admin'), (req, res) => {
  const allUsers = [];
  for (const [id, user] of users) {
    allUsers.push({
      id: user.id,
      username: user.username,
      role: user.role,
      permissions: computeEffectivePermissions(user)
    });
  }
  return res.json(allUsers);
});

// Self-service: update own profile
app.put('/api/profile', authenticate, (req, res) => {
  const { username, currentPassword, newPassword } = req.body;

  if (currentPassword && newPassword) {
    const hash = crypto.createHash('sha256').update(currentPassword + req.user.id).digest('hex');
    if (hash !== req.user.passwordHash) {
      return res.status(403).json({ error: 'Current password incorrect' });
    }
    req.user.passwordHash = crypto.createHash('sha256').update(newPassword + req.user.id).digest('hex');
  }

  if (username) {
    req.user.username = username;
  }

  return res.json({ success: true, username: req.user.username });
});

// Audit log endpoint
app.get('/api/audit', authenticate, (req, res) => {
  const permissions = computeEffectivePermissions(req.user);
  if (!permissions.includes('view_audit')) {
    return res.status(403).json({ error: 'Requires view_audit permission' });
  }

  return res.json({ logs: [] });
});

app.listen(3000, () => console.log('Server running on port 3000'));
